// Generated by OrchestKit Claude Plugin
// Created: 2026-09-14
//
// Helper for tests/unit/test-lab-chrome-injection.sh, not a standalone test.
// Tag-shaped text inside scripts and comments must not steer the Lab chrome
// injection (CodeRabbit on #4101). Prints one PASS/FAIL line per case; the
// shell test counts them.
//
// Usage: node lab-chrome-inert-cases.mjs <path to lab-manifest.mjs>
import { pathToFileURL } from "node:url";

const { injectLabChrome, maskInert } = await import(pathToFileURL(process.argv[2]).href);
const meta = { title: "Real", description: "d", url: "https://x/lab/t.html" };
const out = [];
const t = (ok, label) => out.push(`${ok ? "PASS" : "FAIL"}: ${label}`);

// a. a head script containing "</head>"
const a =
  '<!doctype html><html><head><script>var s="</head>";</script><title>T</title></head><body><p>x</p></body></html>';
const ra = injectLabChrome(a, meta);
const headStart = ra.indexOf("<!-- ork-lab-head:start -->");
t(ra.includes('<script>var s="</head>";</script>'), "inert a: head script text left intact");
t(
  headStart > ra.indexOf("</script>") && headStart < ra.lastIndexOf("</head>"),
  "inert a: head block placed before the real </head>",
);

// b. a script containing a fake og:title meta string
const b =
  "<!doctype html><html><head><title>T</title>" +
  `<script>var m='<meta property="og:title" content="fake">';</script>` +
  "</head><body><p>x</p></body></html>";
const rb = injectLabChrome(b, meta);
t(rb.includes('<meta property="og:title" content="Real">'), "inert b: quoted meta in a script does not suppress the real og:title");
t(rb.includes(`var m='<meta property="og:title" content="fake">';`), "inert b: script text left intact");

// c. a comment containing </body>, after the real </body>
const c = "<!doctype html><html><head><title>T</title></head><body><p>x</p></body><!-- </body> --></html>";
const rc = injectLabChrome(c, meta);
const chromeEnd = rc.indexOf("<!-- ork-lab-chrome:end -->");
t(rc.includes("<!-- </body> -->"), "inert c: comment text left intact");
t(chromeEnd >= 0 && chromeEnd < rc.indexOf("</body>"), "inert c: footer placed before the real </body>, not in the comment");

// Idempotent, and the mask keeps String.slice offsets aligned.
t(
  [a, b, c].every((h) => injectLabChrome(injectLabChrome(h, meta), meta) === injectLabChrome(h, meta)),
  "inert: re-injection is byte-identical",
);
t(
  [a, b, c, "<!-- open \u{1F600} comment"].every((h) => maskInert(h).length === h.length),
  "inert: mask preserves length, including a surrogate pair and an unterminated comment",
);

console.log(out.join("\n"));
